.darma-loader-tw-stacked-cards { position: relative; width: var(--loader-size, 150px); height: calc(var(--loader-size, 150px) * .62); }
.darma-loader-tw-stacked-cards span { position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: calc(var(--loader-size, 150px) * .08); background: var(--loader-color, #6366f1); animation: darma-loader-tw-stacked-cards-twStack calc(var(--loader-speed, 1s) * 2.1) ease-in-out infinite; }
.darma-loader-tw-stacked-cards span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .7); }
.darma-loader-tw-stacked-cards span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.4); }
@keyframes darma-loader-tw-stacked-cards-twStack { 0% { transform: translateY(0) scale(1); opacity: 1; } 33% { transform: translateY(16%) scale(.92); opacity: .65; } 66% { transform: translateY(32%) scale(.84); opacity: .3; } 100% { transform: translateY(0) scale(1); opacity: 1; } }

